// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"O que entra na sala junto com o aluno","html":"<p>O aluno não deixa a vida do lado de fora. Uma noite sem dormir por causa de tiros, a prisão de um parente, a perda de um amigo ou a fome chegam à sala como sono, agitação, silêncio ou agressividade.</p><p>Este guia ajuda a perceber esses sinais, a agir com segurança e a saber até onde vai o papel do professor.</p><h3>Ao final, você será capaz de</h3><ul><li>Reconhecer mudanças de comportamento ligadas a fatores externos.</li><li>Conversar com um aluno que precisa de atenção.</li><li>Saber o que comunicar, a quem e quando.</li><li>Agir com segurança durante uma situação de violência no entorno.</li><li>Conduzir uma conversa difícil com um responsável.</li><li>Cuidar de si.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O professor faz</th><th>O professor não faz</th></tr></thead><tbody><tr><td>Observa, acolhe e registra.</td><td>Investiga a vida do aluno ou da família.</td></tr><tr><td>Comunica à coordenação ou à direção.</td><td>Guarda para si uma suspeita de violência.</td></tr><tr><td>Mantém o vínculo e a rotina da sala.</td><td>Rotula o aluno pelo bairro ou pela família.</td></tr><tr><td>Protege a turma durante uma crise.</td><td>Confronta pessoas do território.</td></tr></tbody></table></div>"},{"id":"c2","titulo":"Sinais de que o aluno precisa de atenção","html":"<p>Nenhum sinal isolado permite concluir nada. O que importa é a <b>mudança</b> em relação ao que o aluno era e a <b>repetição</b> ao longo dos dias.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Área</th><th>O que pode aparecer</th></tr></thead><tbody><tr><td>Presença</td><td>Faltas repetidas, atrasos, saídas antes do fim da aula, sumiço por vários dias.</td></tr><tr><td>Atenção e energia</td><td>Sono em sala, cansaço, dificuldade nova de se concentrar.</td></tr><tr><td>Humor</td><td>Tristeza, irritação, medo, choro fácil, explosões.</td></tr><tr><td>Convivência</td><td>Isolamento, brigas, afastamento dos amigos de sempre.</td></tr><tr><td>Corpo e cuidados</td><td>Fome, falta de material, roupas inadequadas ao clima, descuido incomum.</td></tr><tr><td>Fala e produção</td><td>Desenhos, textos ou comentários sobre violência, morte ou medo.</td></tr><tr><td>Posses e companhias</td><td>Dinheiro ou objetos sem explicação, companhias muito mais velhas, mudança brusca de linguagem.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Cuidado com o rótulo</b><br/>Morar em determinado bairro ou ter um parente envolvido com o crime não define o aluno. A escola pode ser o único lugar onde ele é tratado sem esse peso.</div>"},{"id":"c3","titulo":"Como conversar com o aluno","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Escolher o momento</b><small>em particular, sem pressa</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Dizer o que notou</b><small>fatos, sem julgamento</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Ouvir</b><small>sem pressionar por detalhes</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Acolher</b><small>agradecer a confiança</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Encaminhar</b><small>avisar que vai buscar ajuda</small></div></div><figcaption>Figura. Os passos de uma conversa de acolhimento.</figcaption></figure><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de</th><th>Prefira</th></tr></thead><tbody><tr><td>\"O que está acontecendo na sua casa?\"</td><td>\"Notei que você tem chegado cansado. Quer me contar como você está?\"</td></tr><tr><td>\"Você precisa me contar tudo.\"</td><td>\"Você fala o que quiser e até onde quiser.\"</td></tr><tr><td>\"Prometo não contar a ninguém.\"</td><td>\"Se for algo que coloca você em risco, vou precisar pedir ajuda a quem pode proteger você.\"</td></tr><tr><td>\"Isso não é nada, vai passar.\"</td><td>\"Entendo que isso esteja difícil para você.\"</td></tr></tbody></table></div><div class=\"nota\"><b>Nunca prometa segredo</b><br/>Quando há risco para o aluno, o professor tem o dever de comunicar. Dizer isso com clareza preserva a confiança.</div>"},{"id":"c4","titulo":"O que comunicar e a quem","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Perceber</b><small>mudança que se repete</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Registrar</b><small>data e fato observado</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Comunicar</b><small>coordenação ou direção</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Escola aciona</b><small>família e rede de proteção</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Acompanhar</b><small>manter o vínculo em sala</small></div></div><figcaption>Figura. O caminho da comunicação dentro da escola.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Urgência</th><th>O que fazer</th></tr></thead><tbody><tr><td>Mudança de comportamento sem causa aparente</td><td>Na semana</td><td>Registrar e conversar com a coordenação.</td></tr><tr><td>Suspeita de violência ou negligência</td><td>No mesmo dia</td><td>Comunicar à direção, que comunica ao Conselho Tutelar.</td></tr><tr><td>Aluno relata risco imediato</td><td>Imediata</td><td>Não deixar o aluno sozinho e chamar a direção.</td></tr><tr><td>Aluno ferido</td><td>Imediata</td><td>Acionar a direção e o SAMU, telefone 192.</td></tr><tr><td>Suspeita de aliciamento por grupos do território</td><td>No mesmo dia</td><td>Comunicar à direção, sem confrontar o aluno nem terceiros.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Serviço</th><th>Quando acionar</th><th>Como</th></tr></thead><tbody><tr><td>Conselho Tutelar</td><td>Suspeita ou confirmação de violência, negligência ou violação de direitos de criança ou adolescente.</td><td>Comunicação pela direção da escola. É obrigatória.</td></tr><tr><td>Disque 100</td><td>Denúncia de violação de direitos humanos, inclusive anônima.</td><td>Telefone 100, todos os dias, 24 horas.</td></tr><tr><td>Polícia Militar</td><td>Risco imediato à vida ou crime em andamento.</td><td>Telefone 190.</td></tr><tr><td>SAMU</td><td>Pessoa ferida ou em emergência de saúde.</td><td>Telefone 192.</td></tr><tr><td>CRAS e CREAS</td><td>Família em vulnerabilidade ou com direitos violados.</td><td>Encaminhamento pela direção ou pelo Conselho Tutelar.</td></tr><tr><td>Unidade de saúde e CAPS</td><td>Sofrimento emocional, uso de substâncias ou suspeita de transtorno.</td><td>Encaminhamento pela escola, com a família.</td></tr><tr><td>Ministério Público e Defensoria Pública</td><td>Violação de direitos sem resposta dos demais serviços.</td><td>Pela Secretaria de Educação ou pela direção.</td></tr></tbody></table></div>"},{"id":"c5","titulo":"Violência no entorno: como agir com a turma","html":"<p>As orientações abaixo seguem o guia de Comportamentos Mais Seguros para profissionais da educação, do Comitê Internacional da Cruz Vermelha. Não existe risco zero. O objetivo é reduzir o risco.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Momento</th><th>O que fazer</th><th>O que evitar</th></tr></thead><tbody><tr><td>Antes</td><td>Conhecer o território e os sinais de alerta. Definir o local mais seguro da escola, as rotas e os pontos de encontro. Manter a lista de telefones atualizada.</td><td>Rotas perigosas, mesmo que mais curtas. Deslocar-se sozinho em área de risco.</td></tr><tr><td>Durante disparos</td><td>Deitar-se e orientar os alunos a deitar. Afastar todos de janelas e portas. Levar o grupo, abaixado, ao local mais seguro e permanecer lá.</td><td>Olhar pela janela. Filmar ou fotografar. Usar o telefone antes de estar protegido. Liberar os alunos.</td></tr><tr><td>Depois</td><td>Esperar algum tempo, pois pode haver novos disparos. Confirmar com parceiros do território que a situação normalizou. Avisar a equipe e a Secretaria.</td><td>Sair logo após os disparos. Tocar em armas ou munições. Compartilhar imagens.</td></tr></tbody></table></div><h3>Com a turma, durante o risco</h3><ol class=\"passos\"><li>Fale com voz calma e firme. A turma segue o seu tom.</li><li>Dê instruções curtas: deitar, afastar da janela, ficar junto.</li><li>Conte os alunos.</li><li>Mantenha o grupo ocupado em voz baixa: uma história, uma contagem, uma música conhecida.</li><li>Permaneça com a turma até o aviso da direção.</li></ol><h3>No dia seguinte</h3><ul><li>Reserve um tempo para quem quiser falar. Não obrigue ninguém.</li><li>Retome a rotina. A previsibilidade acalma.</li><li>Observe quem ficou mais abalado e avise a coordenação.</li><li>Evite comentar boatos e não repasse imagens.</li></ul>"},{"id":"c6","titulo":"Conflitos com responsáveis","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Como agir</th></tr></thead><tbody><tr><td>Responsável questiona uma atitude sua</td><td>Ouça até o fim. Explique o que aconteceu e o motivo. Se o tom subir, peça para continuar com a coordenação.</td></tr><tr><td>Responsável exaltado na porta da sala</td><td>Não discuta diante da turma. Chame a coordenação ou a direção.</td></tr><tr><td>Ameaça ou ofensa</td><td>Encerre a conversa, afaste-se e comunique à direção no mesmo dia.</td></tr><tr><td>Responsável pede que você castigue o aluno</td><td>Explique como a escola trata o comportamento e proponha um combinado.</td></tr><tr><td>Família ausente</td><td>Registre as tentativas de contato e leve à coordenação.</td></tr></tbody></table></div><div class=\"nota\"><b>Você não está sozinho</b><br/>Atendimento difícil a um responsável é feito com a presença da coordenação ou da direção, em local reservado, e fica registrado.</div>"},{"id":"c7","titulo":"Exemplos de uso","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · o aluno que passou a dormir em sala</div><p><b>Situação.</b> Um aluno participativo do 7º ano começa a dormir nas primeiras aulas e a faltar às segundas-feiras.</p><p><b>O que fazer.</b></p><ol><li>Anote as datas, sem tirar conclusões.</li><li>Em particular, diga o que notou e pergunte como ele está.</li><li>Leve o registro à coordenação.</li><li>Mantenha as atividades ao alcance dele e evite chamá-lo à atenção diante da turma.</li></ol><p><b>Resultado esperado.</b> A escola entende a causa com a família ou com a rede de proteção, e o aluno segue vinculado à sala.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a turma depois de uma noite de tiros</div><p><b>Situação.</b> A turma chega agitada. Vários alunos contam o que ouviram à noite, e dois estão em silêncio.</p><p><b>O que fazer.</b></p><ol><li>Abra espaço de alguns minutos para falarem, com regras: um por vez, sem detalhes violentos.</li><li>Diga que sentir medo é normal e que a escola é um lugar protegido.</li><li>Retome a rotina com uma atividade simples.</li><li>Observe os dois alunos em silêncio e avise a coordenação.</li></ol><p><b>Resultado esperado.</b> A turma se acalma, e os alunos mais abalados são acompanhados.</p></div>"},{"id":"c8","titulo":"Cuidar de si","html":"<ul><li>Fale com colegas e com a coordenação sobre o que viveu. Guardar para si pesa mais.</li><li>Reconheça os seus limites. Você não resolve sozinho os problemas do território.</li><li>Observe em você sinais de esgotamento: insônia, irritação, vontade de se afastar.</li><li>Procure o serviço de saúde do servidor quando precisar.</li><li>Não permaneça nem se desloque em situação de risco.</li></ul><div class=\"nota\"><b>Apoio emocional</b><br/>O Centro de Valorização da Vida atende pelo telefone 188, todos os dias, 24 horas, sem custo de ligação.</div>"},{"id":"c9","titulo":"Como a violência afeta a aprendizagem","html":"<p>Crianças e adolescentes que convivem com tiroteios, ameaças, perdas e medo constante vivem em estado de alerta. O corpo se prepara o tempo todo para o perigo, e sobra pouca energia para prestar atenção, memorizar e controlar impulsos.</p><p>Muitos comportamentos que a escola lê como desinteresse ou indisciplina são, nesses casos, respostas de quem aprendeu a se proteger.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O que a escola vê</th><th>O que pode estar acontecendo</th></tr></thead><tbody><tr><td>Sono em sala</td><td>Noites sem dormir por medo, barulho ou vigília.</td></tr><tr><td>Sustos e reações exageradas a ruídos</td><td>Estado de alerta permanente.</td></tr><tr><td>Explosões de raiva por motivos pequenos</td><td>Dificuldade de regular emoções sob tensão.</td></tr><tr><td>\"Desligamento\", olhar distante</td><td>Forma de se afastar de lembranças e do medo.</td></tr><tr><td>Esquecimento do que foi ensinado ontem</td><td>A tensão prejudica a memória.</td></tr><tr><td>Desconfiança de adultos</td><td>Experiências em que adultos não protegeram.</td></tr><tr><td>Faltas em determinados dias</td><td>Trajeto inseguro, operações, luto na família.</td></tr><tr><td>Brincadeiras e desenhos com armas e mortes</td><td>Tentativa de dar sentido ao que viu.</td></tr></tbody></table></div><h3>O que ajuda: quatro pilares</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Pilar</th><th>Na prática</th></tr></thead><tbody><tr><td>Segurança</td><td>O aluno sabe que na escola nenhum adulto vai gritar, humilhar ou agredir.</td></tr><tr><td>Previsibilidade</td><td>Rotina conhecida, avisos antes de mudanças, combinados estáveis.</td></tr><tr><td>Vínculo</td><td>Pelo menos um adulto que sabe o nome dele, nota quando falta e pergunta como está.</td></tr><tr><td>Escolha</td><td>Pequenas decisões ao alcance dele: onde sentar, por qual atividade começar.</td></tr></tbody></table></div><div class=\"nota\"><b>Entender não é desculpar</b><br/>Compreender a origem do comportamento não significa abrir mão das regras. Significa aplicá-las com calma, sem humilhação, e ensinar o que o aluno ainda não sabe fazer.</div>"},{"id":"c10","titulo":"Uma sala de aula que protege","html":"<p>O professor não muda o que acontece fora da escola. Pode fazer da sala um lugar onde o aluno baixa a guarda por algumas horas. Isso, por si, melhora a aprendizagem.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Prática</th><th>Como fazer</th><th>Por que funciona</th></tr></thead><tbody><tr><td>Receber na porta</td><td>Cumprimentar cada aluno pelo nome.</td><td>Mostra que ele é esperado e permite notar quem não está bem.</td></tr><tr><td>Rotina no quadro</td><td>Escrever as etapas da aula.</td><td>Quem vive no imprevisto se acalma ao saber o que vem.</td></tr><tr><td>Avisar mudanças</td><td>Dizer antes quando haverá visita, prova ou troca de sala.</td><td>Evita reações de susto.</td></tr><tr><td>Voz calma</td><td>Não gritar, nem com a turma toda.</td><td>O grito aciona o estado de alerta.</td></tr><tr><td>Correção em particular</td><td>Chamar ao lado, em voz baixa.</td><td>Evita humilhação diante do grupo.</td></tr><tr><td>Cantinho de pausa</td><td>Um lugar da sala para se acalmar, com combinado de uso.</td><td>Ensina a se regular sem sair da aula.</td></tr><tr><td>Atividade de chegada</td><td>Tarefa curta e tranquila no início.</td><td>Dá tempo de o corpo \"chegar\".</td></tr><tr><td>Fechamento</td><td>Terminar com algo que deu certo.</td><td>O aluno sai com sensação de capacidade.</td></tr></tbody></table></div><h3>Perguntas que abrem a conversa</h3><ul><li>\"Como você está hoje, de zero a cinco?\"</li><li>\"Tem alguma coisa que eu precise saber para te ajudar hoje?\"</li><li>\"Você prefere começar agora ou em cinco minutos?\"</li><li>\"O que eu posso fazer para a aula ficar melhor para você?\"</li></ul><h3>Um termômetro da turma</h3><p>No início da aula, cada aluno indica como chegou, com um gesto, uma cor ou um número, sem precisar explicar. Leva um minuto e mostra quem precisa de um olhar mais atento naquele dia.</p><div class=\"nota alerta\"><b>Não transforme a aula em terapia</b><br/>O professor acolhe e observa. Não pede que o aluno conte o que viveu diante da turma e não tenta tratar. Quem precisa de atendimento é encaminhado pela coordenação.</div>"},{"id":"c11","titulo":"Com a turma, durante uma ocorrência","html":"<p>Quando há disparos por perto, a turma olha para o professor. A sua calma é o que mais protege. O procedimento abaixo segue as orientações de comportamento mais seguro usadas por redes públicas.</p><ol class=\"passos\"><li>Ao sinal combinado ou ao ouvir disparos, diga com voz firme e calma: \"Todos no chão, longe das janelas.\"</li><li>Abaixe-se você também.</li><li>Leve a turma, abaixada, ao local mais seguro definido no plano. Se não for possível, fiquem no chão, junto às paredes internas.</li><li>Confira se todos estão presentes. Avise a direção se faltar alguém.</li><li>Mantenha os alunos sentados ou deitados, em silêncio ou falando baixo.</li><li>Fique junto dos que estiverem mais assustados.</li><li>Espere a orientação da direção para levantar. Novos disparos podem ocorrer depois de uma pausa.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Não faça</th></tr></thead><tbody><tr><td>Falar pouco, em tom calmo.</td><td>Gritar ou demonstrar pânico.</td></tr><tr><td>Dizer: \"Estamos juntos. Aqui é o lugar mais seguro.\"</td><td>Dizer que não está acontecendo nada.</td></tr><tr><td>Manter todos abaixados.</td><td>Olhar pela janela ou deixar que olhem.</td></tr><tr><td>Guardar o celular até estarem protegidos.</td><td>Filmar, fotografar ou gravar áudios.</td></tr><tr><td>Esperar a liberação da direção.</td><td>Liberar alunos ou sair para ver.</td></tr><tr><td>Ocupar a espera com respiração lenta, contagem ou cantiga baixa, com os menores.</td><td>Comentar o que pode estar acontecendo lá fora.</td></tr></tbody></table></div><h3>Alunos que precisam de apoio</h3><ul><li>Combine antes quem ajuda o aluno com deficiência física ou visual.</li><li>Alunos autistas ou muito ansiosos podem se desorganizar: fique perto, fale pouco e ofereça algo para segurar.</li><li>Quem estiver no banheiro ou no pátio vai para a sala ou o local protegido mais próximo, com qualquer adulto.</li></ul><div class=\"nota\"><b>Depois que passar</b><br/>Mesmo com tudo normalizado, a turma não volta de imediato ao conteúdo. Reserve alguns minutos para beber água, respirar e ouvir quem quiser falar.</div>"},{"id":"c12","titulo":"Conversar com a turma depois","html":"<p>Depois de um episódio de violência, os alunos chegam com o assunto. Fingir que nada aconteceu aumenta o medo. Falar demais também. O caminho é abrir espaço, ouvir e voltar à rotina.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Idade</th><th>Como conduzir</th></tr></thead><tbody><tr><td>6 a 8 anos</td><td>Frases curtas: \"Ontem aconteceu uma coisa que assustou. Os adultos cuidaram de todos.\" Desenho livre. Retomar a rotina logo.</td></tr><tr><td>9 a 11 anos</td><td>Roda rápida: \"Quem quer dizer como está?\" Corrigir boatos com fatos simples. Lembrar o que a escola faz para protegê-los.</td></tr><tr><td>12 a 14 anos</td><td>Conversa mais aberta, sem obrigar. Acolher a raiva sem alimentar ideias de revide. Oferecer a escrita como forma de expressão.</td></tr></tbody></table></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · abrindo a conversa</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Sei que ontem foi um dia difícil no bairro. Antes da aula, quero saber como vocês estão. Fala quem quiser.</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Eu não dormi. Fiquei com medo.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">É natural sentir medo depois de uma coisa assim. Obrigado por contar. Mais alguém?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Dizem que hoje vai ter de novo.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Eu não sei o que vai acontecer lá fora. Sei que aqui a escola tem um combinado para cuidar de todos, e vocês conhecem esse combinado. Vamos lembrar juntos?</div></div></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Evite</th></tr></thead><tbody><tr><td>Ouvir sem corrigir o sentimento.</td><td>Dizer que não foi nada.</td></tr><tr><td>Dizer que sentir medo é normal.</td><td>Pedir detalhes do que viram.</td></tr><tr><td>Lembrar o que a escola faz para proteger.</td><td>Prometer que não vai acontecer de novo.</td></tr><tr><td>Limitar o tempo e retomar a rotina.</td><td>Passar a aula toda no assunto.</td></tr><tr><td>Observar quem ficou calado.</td><td>Deixar circular vídeos e fotos.</td></tr><tr><td>Avisar a coordenação sobre quem está muito abalado.</td><td>Opinar sobre culpados.</td></tr></tbody></table></div><h3>Sinais de que um aluno precisa de mais apoio</h3><ul><li>Semanas depois, continua muito assustado, sem dormir ou sem comer.</li><li>Não consegue se separar dos responsáveis.</li><li>Revive o episódio em brincadeiras e desenhos, sem parar.</li><li>Isola-se ou fica agressivo.</li><li>Fala em vingança ou em se machucar.</li></ul>"},{"id":"c13","titulo":"Luto na escola","html":"<p>A morte de um familiar, de um colega ou de alguém do bairro chega à escola no dia seguinte. A escola não precisa ter respostas. Precisa reconhecer a perda, acolher e manter a rotina.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Idade</th><th>Como costuma reagir</th><th>O que ajuda</th></tr></thead><tbody><tr><td>6 a 8 anos</td><td>Faz perguntas diretas e repetidas. Alterna tristeza e brincadeira. Pode achar que causou a morte.</td><td>Respostas simples e verdadeiras. Dizer que não foi culpa dela. Desenho e brincadeira.</td></tr><tr><td>9 a 11 anos</td><td>Entende que a morte é definitiva. Sente medo de perder outras pessoas. Pode ter dores sem causa médica.</td><td>Espaço para falar. Rotina. Atenção a faltas e queda no rendimento.</td></tr><tr><td>12 a 14 anos</td><td>Esconde o que sente. Pode reagir com raiva, isolamento ou comportamento de risco. Em mortes violentas, pode falar em vingança.</td><td>Conversa em particular, sem pressa. Um adulto de referência. Encaminhamento quando há ideias de revide ou de autolesão.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Dizer</th><th>Evitar</th></tr></thead><tbody><tr><td>\"Sinto muito pelo que aconteceu.\"</td><td>\"Eu sei como você se sente.\"</td></tr><tr><td>\"Estou aqui se você quiser conversar.\"</td><td>\"Você precisa ser forte.\"</td></tr><tr><td>\"Tudo bem chorar.\"</td><td>\"Não chore.\"</td></tr><tr><td>\"Não tenho resposta, mas estou com você.\"</td><td>\"Foi melhor assim\" ou \"foi vontade de Deus\".</td></tr><tr><td>\"Quer fazer a atividade agora ou depois?\"</td><td>\"A vida continua.\"</td></tr></tbody></table></div><h3>Quando morre um aluno ou um servidor</h3><ol class=\"passos\"><li>A direção confirma a informação com a família antes de falar.</li><li>A equipe é reunida e avisada primeiro.</li><li>Cada turma é avisada pelo próprio professor, em sala, com palavras simples e sem detalhes da morte.</li><li>A escola reserva um tempo para os alunos falarem, escreverem ou desenharem.</li><li>A rotina é retomada no mesmo dia, com flexibilidade.</li><li>A escola combina com a família como participar das despedidas.</li><li>Nas semanas seguintes, os professores observam os alunos mais próximos.</li></ol><div class=\"nota alerta\"><b>Em mortes violentas</b><br/>Não se comentam as circunstâncias, não se apontam culpados e não se compartilham imagens. Homenagens são simples e iguais para todos, sem exaltar a forma da morte.</div>"},{"id":"c14","titulo":"O aluno e a história da família","html":"<p>Alguns alunos têm o pai, a mãe ou um irmão presos, mortos ou envolvidos com o crime. Outros são filhos de vítimas ou de agentes de segurança. Todos carregam um peso que não escolheram e têm medo de serem julgados por ele.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação do aluno</th><th>O que ele pode sentir</th><th>O que ajuda</th></tr></thead><tbody><tr><td>Familiar preso</td><td>Vergonha, saudade, medo de que descubram. Faltas em dias de visita.</td><td>Discrição. Não perguntar diante de colegas. Flexibilidade com as faltas, combinada com a coordenação.</td></tr><tr><td>Familiar morto de forma violenta</td><td>Luto, raiva, medo, ideias de revide.</td><td>Acolhimento, adulto de referência, encaminhamento pela coordenação.</td></tr><tr><td>Familiar envolvido com o crime</td><td>Lealdade dividida, silêncio, por vezes orgulho.</td><td>Tratar como qualquer aluno. Não falar da família. Abrir outros horizontes.</td></tr><tr><td>Família ameaçada ou que precisou se mudar</td><td>Medo constante, dificuldade de fazer amigos.</td><td>Acolhida na turma, sem perguntas sobre a origem.</td></tr><tr><td>Filho de agente de segurança</td><td>Medo de ser identificado.</td><td>Sigilo sobre a profissão dos responsáveis.</td></tr></tbody></table></div><h3>Cuidados nas atividades</h3><ul><li>Em datas e trabalhos sobre a família, ofereça alternativas: \"alguém que cuida de você\", \"uma pessoa importante\".</li><li>Não peça que os alunos contem a profissão dos pais diante da turma.</li><li>Em redações e desenhos, trate com reserva o que o aluno revelar.</li><li>Não comente com outros responsáveis o que sabe de uma família.</li><li>Interrompa na hora qualquer provocação entre alunos sobre familiares.</li></ul><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · quando um colega provoca</div><div class=\"f\"><div class=\"q\">Aluno A</div><div class=\"b\">O pai dele está preso!</div></div><div class=\"f o\"><div class=\"q\">Professor</div><div class=\"b\">Aqui ninguém fala da família de ninguém. Esse é o nosso combinado. Voltem à atividade.</div></div><div class=\"f o\"><div class=\"q\">Professor</div><div class=\"b\">(depois, em particular, ao aluno provocado) Vi o que aconteceu. Você não precisa me explicar nada. Se alguém voltar a te incomodar, me avise.</div></div></div><div class=\"nota\"><b>O aluno não é a família</b><br/>Nenhuma criança responde pelo que os adultos da casa fazem. Na escola, ela tem o direito de ser apenas aluna.</div>"},{"id":"c15","titulo":"Quando o crime tenta atrair alunos","html":"<p>Em alguns territórios, grupos criminosos procuram adolescentes, e às vezes crianças, para tarefas como vigiar, transportar e vender. A aproximação raramente começa com ameaça. Começa com dinheiro, presentes, proteção e a sensação de pertencer a um grupo.</p><p>A lei trata esses adolescentes como vítimas de exploração. O uso de crianças e adolescentes no tráfico está na lista das piores formas de trabalho infantil (Decreto nº 6.481/2008).</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Fatores de risco</th><th>Fatores de proteção</th></tr></thead><tbody><tr><td>Faltas e abandono escolar.</td><td>Frequência e vínculo com a escola.</td></tr><tr><td>Sensação de não ter futuro pelo estudo.</td><td>Experiências de sucesso e projeto de vida.</td></tr><tr><td>Necessidade de renda na família.</td><td>Acesso a programas sociais e de aprendizagem profissional.</td></tr><tr><td>Familiares ou amigos envolvidos.</td><td>Um adulto de referência fora desse círculo.</td></tr><tr><td>Humilhação e exclusão na escola.</td><td>Respeito e pertencimento na turma.</td></tr><tr><td>Tempo livre sem supervisão.</td><td>Esporte, cultura e atividades no contraturno.</td></tr></tbody></table></div><h3>Sinais que pedem atenção</h3><ul><li>Dinheiro, roupas ou aparelhos sem explicação.</li><li>Novo grupo de amizades, mais velho, e afastamento dos colegas antigos.</li><li>Faltas que aumentam, sono em sala, saídas antes do fim da aula.</li><li>Gírias, gestos e símbolos ligados a grupos do território.</li><li>Mudança de postura: desafio aos adultos ou, ao contrário, medo e silêncio.</li><li>Comentários sobre dívidas, ameaças ou \"missões\".</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>A escola faz</th><th>A escola não faz</th></tr></thead><tbody><tr><td>Mantém o aluno na escola a todo custo.</td><td>Não expulsa, não transfere como punição e não rotula.</td></tr><tr><td>Conversa sobre futuro, sem sermão.</td><td>Não interroga sobre o envolvimento.</td></tr><tr><td>Leva à direção, que aciona a rede de proteção.</td><td>Não confronta pessoas do território.</td></tr><tr><td>Oferece atividades, responsabilidades e reconhecimento.</td><td>Não repassa nomes ou informações a ninguém fora da rede de proteção.</td></tr><tr><td>Trata com a família, com cuidado.</td><td>Não expõe a suspeita a colegas ou a outros responsáveis.</td></tr></tbody></table></div><div class=\"nota\"><b>Adolescentes ameaçados</b><br/>Quando há ameaça de morte contra um aluno, a direção comunica imediatamente ao Conselho Tutelar e à Secretaria. Existe um programa federal de proteção a crianças e adolescentes ameaçados de morte, acionado pelo Conselho Tutelar, pelo Ministério Público ou pela Justiça.</div>"},{"id":"c16","titulo":"Falas, símbolos e brincadeiras sobre o crime","html":"<p>Alunos que crescem perto de grupos armados reproduzem o que veem: gestos, gírias, músicas, desenhos de armas, brincadeiras de \"polícia e bandido\". Na maioria das vezes, não é adesão. É o repertório do lugar.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Como responder</th><th>O que evitar</th></tr></thead><tbody><tr><td>Desenhos de armas e de mortes</td><td>Perguntar, com interesse: \"Me conta o seu desenho.\" Observar se é registro do que viu.</td><td>Rasgar, proibir ou expor.</td></tr><tr><td>Brincadeira de tiroteio</td><td>Redirecionar para outra brincadeira, sem bronca. Observar se há sofrimento.</td><td>Punir como indisciplina grave.</td></tr><tr><td>Gestos e símbolos de grupos</td><td>Dizer em particular que na escola não se usam símbolos de grupos, e explicar que isso protege a todos.</td><td>Confrontar diante da turma ou perguntar sobre o grupo.</td></tr><tr><td>Aluno que diz admirar pessoas do crime</td><td>Perguntar o que ele admira: dinheiro, respeito, proteção? Conversar sobre outros caminhos para isso.</td><td>Sermão ou ameaça.</td></tr><tr><td>Aluno que usa o medo para intimidar colegas ou adultos</td><td>Limite firme, em particular. Comunicar à direção.</td><td>Ceder ou responder com outra ameaça.</td></tr><tr><td>Músicas com apologia à violência</td><td>Regra geral da escola sobre o que se ouve no espaço escolar. Propor análise crítica de letras nas aulas.</td><td>Desqualificar o gosto do aluno.</td></tr></tbody></table></div><h3>O que a aula pode oferecer</h3><ul><li>Experiências de sucesso: o aluno precisa sentir que é bom em alguma coisa.</li><li>Adultos que tratam com respeito e cobram com justiça.</li><li>Contato com pessoas do bairro que construíram caminhos pelo estudo e pelo trabalho.</li><li>Projetos em que o aluno tem voz e responsabilidade.</li><li>Informação sobre cursos, aprendizagem profissional, esporte e cultura.</li><li>Conversas sobre futuro que partem do que ele quer, e não do que o adulto teme.</li></ul><div class=\"pratica\"><div class=\"tt\">Para praticar · projeto de vida</div><div class=\"q\"><b>1.</b> Que atividade da sua disciplina permite ao aluno falar do futuro que deseja?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Quem, no bairro ou na cidade, você poderia convidar para conversar com a turma?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c17","titulo":"Substâncias e objetos perigosos em sala","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>O que o professor faz</th><th>O que o professor não faz</th></tr></thead><tbody><tr><td>Aluno parece sob efeito de substância</td><td>Mantém a calma, cuida da segurança dele e avisa a direção, que aciona os responsáveis e a saúde.</td><td>Não acusa nem expõe diante da turma.</td></tr><tr><td>Vê uma substância com o aluno</td><td>Avisa a direção com discrição.</td><td>Não revista, não toma à força e não descarta.</td></tr><tr><td>Suspeita de venda entre alunos</td><td>Relata à direção o que observou.</td><td>Não investiga, não monta flagrante e não confronta.</td></tr><tr><td>Aluno com faca, arma ou objeto perigoso</td><td>Não se aproxima de forma brusca. Afasta os demais com um pretexto e avisa a direção imediatamente.</td><td>Não tenta desarmar.</td></tr><tr><td>Encontra arma ou munição</td><td>Isola o local e chama a direção, que aciona o 190.</td><td>Não toca nem fotografa para grupos.</td></tr><tr><td>Aluno conta que um colega tem uma arma</td><td>Agradece, garante sigilo e avisa a direção.</td><td>Não vai conferir sozinho.</td></tr></tbody></table></div><h3>Falar de drogas com a turma</h3><ul><li>Prefira informação correta e conversa a discursos de medo, que os alunos desacreditam.</li><li>Trabalhe a capacidade de dizer não e de lidar com a pressão do grupo.</li><li>Fale também de álcool e de cigarros eletrônicos, que costumam vir antes.</li><li>Não peça relatos pessoais diante da turma.</li><li>Mostre onde buscar ajuda: unidade de saúde e CAPS.</li><li>Combine o trabalho com a coordenação e com a rede de saúde.</li></ul><div class=\"nota\"><b>O adolescente que usa precisa de cuidado</b><br/>O uso de substâncias por adolescentes é tratado como questão de saúde e de proteção. O papel da escola é acolher, chamar a família e encaminhar.</div>"},{"id":"c18","titulo":"Frequência: o professor é o primeiro a perceber","html":"<p>Antes de abandonar a escola, o aluno dá sinais. O professor, que faz a chamada todos os dias, é quem primeiro pode notar.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Sinal</th><th>O que pode haver</th><th>O que fazer</th></tr></thead><tbody><tr><td>Faltas em dias fixos</td><td>Trabalho, visita a familiar, trajeto.</td><td>Perguntar com cuidado e avisar a coordenação.</td></tr><tr><td>Faltas depois de um episódio no bairro</td><td>Medo, luto, mudança.</td><td>Avisar a secretaria da escola no mesmo dia.</td></tr><tr><td>Atrasos frequentes</td><td>Trajeto mais longo para evitar uma área, cuidado de irmãos.</td><td>Acolher a chegada e conversar depois.</td></tr><tr><td>Saídas antes do fim</td><td>Horário de risco no trajeto, trabalho.</td><td>Informar a coordenação.</td></tr><tr><td>Presença sem participação</td><td>O aluno está de corpo presente e pensa em outra coisa.</td><td>Conversa em particular.</td></tr><tr><td>Aluno diz que vai sair da escola</td><td>Decisão em curso.</td><td>Ouvir os motivos e levar à coordenação no mesmo dia.</td></tr></tbody></table></div><h3>Quando o aluno volta</h3><ul><li>Diga que sentiu falta dele.</li><li>Não pergunte o motivo diante da turma.</li><li>Entregue um resumo do que foi estudado.</li><li>Combine como ele vai recuperar, com prazo possível.</li><li>Use o reforço escolar para retomar as habilidades que ficaram para trás.</li><li>Escolha um colega para ajudá-lo nos primeiros dias.</li></ul><div class=\"nota\"><b>A chamada é um ato de cuidado</b><br/>Notar quem faltou e avisar no mesmo dia é uma das ações mais simples e mais eficazes contra o abandono escolar.</div>"},{"id":"c19","titulo":"Conversas com responsáveis em contextos difíceis","html":"<p>Muitas famílias do território vivem sob tensão, trabalham em horários difíceis e têm lembranças ruins da escola. Algumas evitam aparecer por medo de serem julgadas. A conversa com elas pede cuidado redobrado.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>Na prática</th></tr></thead><tbody><tr><td>Comece pelo que o aluno tem de bom</td><td>Toda conversa abre com um ponto forte, verdadeiro e específico.</td></tr><tr><td>Fale do que se vê na escola</td><td>Não pergunte sobre a vida da família, o bairro ou o trabalho dos responsáveis.</td></tr><tr><td>Não culpe</td><td>\"O que podemos fazer juntos?\" funciona melhor do que \"a senhora precisa\".</td></tr><tr><td>Peça ajuda</td><td>A família conhece o aluno: pergunte o que funciona em casa.</td></tr><tr><td>Respeite o tempo</td><td>Ofereça horários alternativos e conversa por telefone.</td></tr><tr><td>Guarde sigilo</td><td>O que a família conta não é comentado com outros responsáveis nem na sala dos professores.</td></tr></tbody></table></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · a mãe que evita a escola</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Dona Rita, obrigado por atender. Estou ligando para dizer que o Caio tem participado muito bem das aulas de leitura.</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Ah, que bom. Achei que era reclamação.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Não é. Queria também a sua ajuda. Ele tem faltado às sextas. Aconteceu alguma coisa?</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">É que na sexta eu saio muito cedo e não tem quem leve.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Entendi. Vou conversar com a coordenação para ver o que a escola pode fazer. Posso ligar de novo na semana que vem?</div></div></div><h3>Quando o responsável está alterado</h3><ul><li>Não atenda sozinho nem na sala de aula. Encaminhe à direção.</li><li>Mantenha a voz baixa e não responda a provocações.</li><li>Diga: \"Quero ouvir o senhor. Vamos à direção, para conversar com calma.\"</li><li>Se houver ameaça, afaste-se e avise a direção.</li><li>Registre o ocorrido por escrito no mesmo dia.</li></ul><div class=\"nota alerta\"><b>Visitas e contatos fora da escola</b><br/>O professor não visita casas de alunos por conta própria e não usa o telefone pessoal para tratar de assuntos escolares. Contatos são feitos pelos canais da escola e, quando necessário, por equipe designada pela direção.</div>"},{"id":"c20","titulo":"A segurança do professor","html":"<p>Cuidar de si faz parte do trabalho. As orientações abaixo reduzem a exposição no trajeto, na escola e nas redes.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Momento</th><th>Cuidados</th></tr></thead><tbody><tr><td>No trajeto</td><td>Conhecer mais de um caminho. Informar-se com colegas antes de sair em dias de tensão. Evitar chegar ou sair sozinho em horários vazios. Seguir a orientação da direção sobre suspensão de aulas.</td></tr><tr><td>Na escola</td><td>Conhecer o plano de segurança e o local mais seguro da sua sala. Não atender sozinho pessoas alteradas. Manter a porta da sala desobstruída.</td></tr><tr><td>Com os alunos</td><td>Tratar todos com o mesmo respeito. Não comentar o território. Não fazer perguntas sobre familiares. Corrigir sem humilhar.</td></tr><tr><td>Nas redes sociais</td><td>Não publicar a rotina, o endereço nem imagens de alunos. Não comentar ocorrências do bairro. Não aceitar alunos em perfis pessoais.</td></tr><tr><td>Com informações</td><td>O que souber sobre alunos, famílias e território fica na escola. Não repassar a terceiros.</td></tr></tbody></table></div><h3>Se você for ameaçado</h3><ol class=\"passos\"><li>Não responda nem discuta.</li><li>Afaste-se e procure a direção imediatamente.</li><li>Registre por escrito o que foi dito, quando e onde.</li><li>A direção comunica à Secretaria, que orienta as providências e o registro da ocorrência.</li><li>Não volte sozinho para casa no mesmo dia, se houver risco.</li><li>Procure o apoio de saúde do servidor.</li></ol><div class=\"nota\"><b>Limites que protegem</b><br/>Ser acolhedor não exige ser confidente. O professor não precisa saber detalhes da vida do território para ajudar o aluno. Saber menos, nesse caso, também protege.</div>"},{"id":"c21","titulo":"Neutralidade e cuidado com as palavras","html":"<p>A escola atende filhos de todas as famílias do território, inclusive de pessoas envolvidas com o crime, de vítimas e de agentes de segurança. Para continuar sendo um lugar seguro para todos, ela não toma partido.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>Como se traduz no dia a dia</th></tr></thead><tbody><tr><td>Todos os alunos são alunos</td><td>Nenhum aluno é tratado de modo diferente pelo que a família faz ou pelo lugar onde mora.</td></tr><tr><td>A escola não comenta o território</td><td>Servidores não opinam sobre grupos, operações ou pessoas diante de alunos e responsáveis.</td></tr><tr><td>A escola não repassa informação</td><td>O que se sabe sobre alunos e famílias fica na escola e na rede de proteção.</td></tr><tr><td>A escola não aceita favores</td><td>Doações, festas e \"ajudas\" de origem duvidosa são recusadas com educação e comunicadas à Secretaria.</td></tr><tr><td>A escola não media disputas</td><td>Conflitos do território não são resolvidos dentro da escola.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Evitar dizer</th><th>Prefira</th></tr></thead><tbody><tr><td>\"Aqui só tem bandido.\"</td><td>\"Este bairro enfrenta muita violência.\"</td></tr><tr><td>\"Filho de traficante.\"</td><td>O nome do aluno.</td></tr><tr><td>\"Esse aí já está perdido.\"</td><td>\"Esse aluno precisa de mais apoio.\"</td></tr><tr><td>\"Você vai acabar como seu irmão.\"</td><td>\"Você pode escolher o seu caminho, e eu quero ajudar.\"</td></tr><tr><td>\"A polícia tem que acabar com eles.\"</td><td>Não comentar.</td></tr><tr><td>\"Lá na área de vocês...\"</td><td>\"No bairro...\"</td></tr></tbody></table></div><div class=\"nota\"><b>O que o aluno ouve</b><br/>Uma frase dita por um adulto da escola sobre o bairro ou sobre a família é levada para casa. Pode ferir o aluno e pode colocar o servidor em risco.</div>"},{"id":"c22","titulo":"Boatos, redes sociais e ameaças","html":"<p>Mensagens sobre tiroteios, toques de recolher e ameaças a escolas se espalham em minutos pelos grupos. Muitas são falsas, antigas ou de outra cidade. Mesmo assim, esvaziam a escola e geram pânico.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Receber</b><small>não repassar</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Verificar</b><small>com a direção e fontes oficiais</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Comunicar</b><small>à Secretaria</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Informar</b><small>famílias, por canal oficial</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Registrar</b><small>o que ocorreu</small></div></div><figcaption>Figura. O que fazer ao receber uma mensagem alarmante.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td>Mensagem sobre confronto no bairro</td><td>A direção confirma com parceiros do território e com a Secretaria antes de qualquer decisão.</td></tr><tr><td>Boato de \"toque de recolher\"</td><td>A direção comunica à Secretaria, que orienta. A escola não divulga o boato.</td></tr><tr><td>Ameaça de ataque à escola em rede social</td><td>Guardar a imagem da mensagem, comunicar à direção e à Secretaria, que acionam a polícia. Não compartilhar.</td></tr><tr><td>Aluno que escreve ou desenha ameaças</td><td>Tratar com seriedade e sem pânico. Conversar em particular, comunicar à direção e chamar a família.</td></tr><tr><td>Responsáveis pedem informação</td><td>Responder apenas pelo canal oficial da escola, com o que foi confirmado.</td></tr><tr><td>Imprensa procura a escola</td><td>Encaminhar à Secretaria. Servidores não dão entrevistas sobre ocorrências.</td></tr></tbody></table></div><h3>Regras para os grupos de mensagens</h3><ul><li>A escola tem um canal oficial, e os responsáveis sabem qual é.</li><li>Servidores não repassam áudios, vídeos e mensagens não confirmados.</li><li>Nenhuma imagem de alunos, de vítimas ou de ocorrências é compartilhada.</li><li>Informações sobre o território não são comentadas em grupos.</li><li>Quem recebe algo preocupante envia só à direção.</li></ul><div class=\"nota alerta\"><b>Ameaças de ataque</b><br/>Toda ameaça é comunicada, mesmo que pareça brincadeira. Quem avalia a gravidade é a autoridade policial. A escola cuida de acolher, informar com calma e manter a rotina que for possível.</div>"},{"id":"c23","titulo":"Mais casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · o desenho</div><p><b>Situação.</b> Um aluno do 3º ano desenha, por vários dias, homens armados e uma pessoa caída.</p><p><b>O que fazer.</b></p><ol><li>Não repreenda nem recolha o desenho diante da turma.</li><li>Em particular, diga: \"Me conta o seu desenho.\"</li><li>Ouça sem pedir detalhes.</li><li>Registre o que ele disse e leve à coordenação.</li><li>Mantenha a rotina e ofereça outras formas de expressão.</li></ol><p><b>Resultado esperado.</b> A coordenação conversa com a família e avalia o encaminhamento à rede de saúde.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o tênis novo</div><p><b>Situação.</b> Um aluno do 8º ano, que faltava muito, aparece com roupas caras e dinheiro. Diz aos colegas que \"arrumou um trabalho\".</p><p><b>O que fazer.</b></p><ol><li>Não pergunte sobre o trabalho diante de ninguém.</li><li>Mantenha a relação de respeito e procure momentos de conversa sobre o que ele quer para o futuro.</li><li>Relate à direção o que observou, sem conclusões.</li><li>A direção aciona a rede de proteção e conversa com a família.</li><li>A escola busca vaga em atividade de contraturno ou em programa de aprendizagem.</li></ol><p><b>Resultado esperado.</b> O aluno mantém a matrícula e passa a ter acompanhamento da rede.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a provocação entre bairros</div><p><b>Situação.</b> Dois grupos de alunos do 9º ano, de localidades diferentes, trocam provocações que repetem rivalidades de fora.</p><p><b>O que fazer.</b></p><ol><li>Interrompa na hora, sem tomar lado.</li><li>Reforce a regra: na escola não entram disputas do bairro.</li><li>Mude a formação dos grupos de trabalho, misturando os alunos.</li><li>Comunique à direção, que avalia o risco no trajeto e na saída.</li><li>Proponha um projeto em que os dois grupos dependam um do outro.</li></ol><p><b>Resultado esperado.</b> A tensão diminui dentro da escola, e a direção acompanha a saída dos alunos.</p></div><div class=\"pratica\"><div class=\"tt\">Para praticar · a sua sala</div><div class=\"q\"><b>1.</b> Qual é o local mais seguro da sua sala e o caminho até ele?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que frase você dirá à turma no momento de uma ocorrência?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Que aluno, hoje, precisa de um adulto de referência? O que você pode fazer nesta semana?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c24","titulo":"Práticas para acalmar o corpo e a atenção","html":"<p>Alunos em estado de alerta não conseguem aprender. Práticas curtas, de um a três minutos, ajudam o corpo a baixar a tensão. Elas servem para a turma toda e não exigem material.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Prática</th><th>Como fazer</th><th>Quando usar</th></tr></thead><tbody><tr><td>Respiração do quadrado</td><td>Inspirar contando até quatro, segurar por quatro, soltar em quatro, esperar quatro. Repetir quatro vezes.</td><td>No início da aula e depois do recreio.</td></tr><tr><td>Cinco sentidos</td><td>Nomear em silêncio cinco coisas que vê, quatro que ouve, três que toca.</td><td>Depois de um susto ou de uma discussão.</td></tr><tr><td>Apertar e soltar</td><td>Fechar as mãos com força por cinco segundos e soltar. Repetir com ombros e pés.</td><td>Antes de uma prova ou de uma atividade difícil.</td></tr><tr><td>Contagem regressiva</td><td>Contar de dez a zero, cada vez mais baixo.</td><td>Para voltar ao silêncio sem gritar.</td></tr><tr><td>Minuto de silêncio</td><td>Um minuto de olhos fechados ou olhando um ponto, ouvindo os sons da sala.</td><td>Na transição entre atividades.</td></tr><tr><td>Alongamento</td><td>Levantar, esticar os braços, girar os ombros.</td><td>No meio de aulas longas.</td></tr><tr><td>Desenho livre</td><td>Três minutos de desenho ou rabisco.</td><td>Para alunos menores, em dias agitados.</td></tr><tr><td>Escrita rápida</td><td>Três minutos escrevendo o que vier, sem entregar.</td><td>Para alunos maiores, depois de um episódio no bairro.</td></tr></tbody></table></div><h3>Como introduzir</h3><ul><li>Apresente como um treino de atenção, e não como brincadeira ou castigo.</li><li>Faça junto com a turma.</li><li>Ninguém é obrigado a fechar os olhos.</li><li>Repita todos os dias, no mesmo momento, até virar rotina.</li><li>Não use logo depois de uma bronca.</li></ul><h3>Para um aluno muito agitado ou assustado</h3><ol class=\"passos\"><li>Aproxime-se com calma e fale baixo.</li><li>Ofereça água ou um lugar mais tranquilo.</li><li>Proponha respirar junto: \"vamos soltar o ar bem devagar\".</li><li>Não faça perguntas naquele momento.</li><li>Quando ele estiver mais calmo, pergunte do que precisa.</li><li>Avise a coordenação se a situação se repetir.</li></ol><div class=\"nota\"><b>Não é tratamento</b><br/>Essas práticas ajudam a turma a se concentrar. Alunos com sofrimento persistente precisam de atendimento na rede de saúde, encaminhado pela coordenação.</div>"},{"id":"c25","titulo":"A roda de conversa","html":"<p>A roda de conversa dá à turma um lugar seguro para falar e ouvir. Usada com regularidade, melhora a convivência e permite ao professor perceber o que os alunos vivem.</p><ol class=\"passos\"><li>Forme um círculo, com todos no mesmo nível, inclusive você.</li><li>Relembre os combinados: fala um por vez, ninguém é obrigado a falar, ninguém comenta a fala do outro, o que é dito fica na roda.</li><li>Use um objeto que passa de mão em mão e indica quem fala.</li><li>Faça uma pergunta de abertura simples: \"uma coisa boa da semana\".</li><li>Faça a pergunta principal.</li><li>Agradeça cada fala, sem avaliar.</li><li>Feche com uma rodada curta: \"uma palavra sobre como você sai\".</li></ol><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Objetivo</th><th>Perguntas possíveis</th></tr></thead><tbody><tr><td>Conhecer a turma</td><td>\"O que eu gosto de fazer quando não estou na escola?\" \"Uma coisa em que eu sou bom.\"</td></tr><tr><td>Convivência</td><td>\"O que faz uma pessoa se sentir bem nesta turma?\" \"O que incomoda?\"</td></tr><tr><td>Depois de um conflito</td><td>\"O que aconteceu, na visão de cada um?\" \"O que precisamos para seguir?\"</td></tr><tr><td>Depois de um episódio no bairro</td><td>\"Como você está hoje?\" \"O que ajuda quando a gente sente medo?\"</td></tr><tr><td>Projeto de vida</td><td>\"Como eu me imagino daqui a cinco anos?\" \"Quem eu admiro e por quê?\"</td></tr><tr><td>Avaliação da aula</td><td>\"O que me ajuda a aprender?\" \"O que eu mudaria nas nossas aulas?\"</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Se acontecer</th><th>O que fazer</th></tr></thead><tbody><tr><td>Um aluno conta algo grave</td><td>Agradecer, não pedir detalhes diante do grupo, conversar em particular depois e comunicar à direção.</td></tr><tr><td>Um aluno zomba da fala de outro</td><td>Interromper, lembrar o combinado e seguir.</td></tr><tr><td>Ninguém fala</td><td>Começar você, com uma fala curta e verdadeira. Usar perguntas mais simples.</td></tr><tr><td>Um aluno ocupa todo o tempo</td><td>Lembrar que cada um fala uma vez por rodada.</td></tr><tr><td>Surge um assunto do território</td><td>Ouvir os sentimentos, sem comentar fatos, pessoas ou culpados.</td></tr><tr><td>Alguém chora</td><td>Acolher com naturalidade, oferecer que saia com um colega para beber água e seguir.</td></tr></tbody></table></div><div class=\"nota\"><b>Regularidade</b><br/>Uma roda de quinze minutos por semana vale mais do que uma hora em um dia de crise. A turma precisa conhecer o formato antes de precisar dele.</div>"},{"id":"c26","titulo":"A rede de apoio vista da sala de aula","html":"<p>O professor não aciona diretamente os serviços da rede, mas precisa saber o que cada um faz para explicar ao aluno e à família e para entender o que acontece depois que comunica algo à direção.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Serviço</th><th>O que faz</th><th>O que o professor pode esperar</th></tr></thead><tbody><tr><td>Conselho Tutelar</td><td>Zela pelos direitos da criança e do adolescente. Recebe as comunicações da escola e aplica medidas de proteção.</td><td>Pode pedir informações à escola. Nem sempre pode dar retorno, por sigilo.</td></tr><tr><td>CRAS</td><td>Atende famílias em situação de vulnerabilidade: cadastro em programas, grupos, orientação.</td><td>A família pode passar a receber apoio que melhora a frequência.</td></tr><tr><td>CREAS</td><td>Atende famílias e pessoas com direitos violados: violência, abuso, trabalho infantil.</td><td>Acompanhamento mais longo, com sigilo.</td></tr><tr><td>Unidade básica de saúde</td><td>Primeira avaliação de saúde, vacinação, encaminhamentos.</td><td>A família pode levar um relatório da escola.</td></tr><tr><td>CAPS infantojuvenil</td><td>Atende sofrimento psíquico intenso e uso de substâncias.</td><td>O aluno pode ter horários de atendimento que geram faltas justificadas.</td></tr><tr><td>Psicologia e serviço social da educação</td><td>Onde a rede dispõe desses profissionais, apoiam as escolas, conforme a Lei nº 13.935/2019.</td><td>Orientação à equipe e apoio nos casos.</td></tr><tr><td>Ministério Público e Defensoria</td><td>Atuam quando direitos não são garantidos.</td><td>Acionados pela direção ou pela Secretaria.</td></tr></tbody></table></div><h3>O que o professor faz</h3><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Perceber</b><small>observar e registrar</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Comunicar</b><small>à direção, no mesmo dia</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Acolher</b><small>manter o vínculo e a rotina</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Acompanhar</b><small>observar mudanças</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Informar</b><small>novos sinais à direção</small></div></div><figcaption>Figura. O papel do professor na rede de proteção.</figcaption></figure><h3>O que o professor não faz</h3><ul><li>Não procura os serviços por conta própria, em nome da escola.</li><li>Não visita a família.</li><li>Não promete ao aluno o que a rede vai fazer.</li><li>Não cobra da família o resultado do atendimento.</li><li>Não comenta o caso com outras pessoas.</li></ul><div class=\"nota\"><b>Quando parece que nada acontece</b><br/>A rede tem tempos e limites próprios. Se os sinais continuam, comunique de novo à direção. A insistência da escola faz diferença.</div>"},{"id":"c27","titulo":"Perguntas frequentes","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Resposta</th></tr></thead><tbody><tr><td>Devo perguntar ao aluno o que aconteceu no bairro?</td><td>Não. Pergunte como ele está. Se ele quiser contar, ouça sem pedir detalhes.</td></tr><tr><td>Um aluno me contou algo sobre pessoas do território. O que faço?</td><td>Não repasse a ninguém fora da direção. Não comente com colegas.</td></tr><tr><td>Posso aconselhar um aluno a se afastar de certas amizades?</td><td>Fale do futuro que ele quer e do que o aproxima ou afasta disso. Sermões afastam.</td></tr><tr><td>E se eu tiver medo de um aluno?</td><td>Diga à direção. Ninguém deve trabalhar com medo sem apoio.</td></tr><tr><td>Posso levar um aluno em casa em dia de tensão?</td><td>Não. A entrega dos alunos segue o plano da escola.</td></tr><tr><td>Um responsável me pediu o meu telefone.</td><td>Informe o canal da escola. Não use o número pessoal.</td></tr><tr><td>Devo abordar o tema da violência nas aulas?</td><td>Sim, de forma pedagógica e combinada com a coordenação, sem citar fatos e pessoas do bairro.</td></tr><tr><td>Um aluno faltou uma semana depois de uma morte na família.</td><td>Avise a secretaria da escola. Na volta, acolha e combine como recuperar.</td></tr><tr><td>O aluno desenha armas o tempo todo.</td><td>Pergunte sobre o desenho, sem proibir. Leve à coordenação o que ele disser.</td></tr><tr><td>Vi algo estranho perto da escola.</td><td>Avise a direção com discrição. Não investigue nem fotografe.</td></tr><tr><td>Um aluno me ameaçou.</td><td>Afaste-se, avise a direção e registre.</td></tr><tr><td>Posso opinar sobre uma operação policial?</td><td>Não diante de alunos e responsáveis.</td></tr><tr><td>O que digo quando perguntam se a escola é segura?</td><td>\"A escola tem um plano para cuidar de todos, e nós treinamos esse plano.\"</td></tr><tr><td>Como cuido de mim?</td><td>Divida com a equipe, respeite os seus limites e procure o serviço de saúde do servidor quando precisar.</td></tr></tbody></table></div>"},{"id":"c28","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"O que comunicar e a quem\"</td><td>Que sinais já observamos? O nosso fluxo de comunicação é claro?</td></tr><tr><td>2</td><td>De \"Violência no entorno\" até \"Uma sala de aula que protege\"</td><td>O que nas nossas salas ajuda um aluno a baixar a guarda? O que atrapalha?</td></tr><tr><td>3</td><td>\"Com a turma, durante uma ocorrência\", \"Conversar depois\" e \"Luto\"</td><td>Cada um sabe o local mais seguro da sua sala? Como falamos com as turmas depois?</td></tr><tr><td>4</td><td>De \"O aluno e a história da família\" até \"Substâncias e objetos perigosos\"</td><td>Como tratamos os alunos cujas famílias são comentadas? O que oferecemos como alternativa?</td></tr><tr><td>5</td><td>De \"Frequência\" até o final</td><td>Como avisamos as faltas? Que cuidados de segurança adotamos?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c29","titulo":"Referências","html":"<ul><li>Estatuto da Criança e do Adolescente (Lei nº 8.069/1990), arts. 13, 56 e 245.</li><li>Lei nº 13.431/2017, sobre a escuta de crianças e adolescentes vítimas ou testemunhas de violência.</li><li>Lei nº 14.643/2023, que autoriza o Sistema Nacional de Acompanhamento e Combate à Violência nas Escolas.</li><li>Lei nº 13.935/2019, sobre serviços de psicologia e de serviço social nas redes públicas de educação básica.</li><li>Comitê Internacional da Cruz Vermelha: metodologia Acesso Mais Seguro para Serviços Públicos Essenciais e guia de Comportamentos Mais Seguros para profissionais da educação.</li><li>Ministério da Educação: programa Escola que Protege.</li></ul>"},{"id":"c30","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> O sinal mais importante de que um aluno precisa de atenção é:</p><ol type=\"a\"><li>Uma mudança de comportamento que se repete.</li><li>Uma nota baixa.</li><li>Ter um parente preso.</li><li>Morar em bairro violento.</li></ol></div><div class=\"qz\"><p><b>2.</b> Um aluno pede segredo antes de contar algo. O adequado é dizer:</p><ol type=\"a\"><li>\"Então não me conte.\"</li><li>\"Só conto para a turma.\"</li><li>\"Prometo não contar.\"</li><li>\"Se for algo que coloca você em risco, vou precisar pedir ajuda.\"</li></ol></div><div class=\"qz\"><p><b>3.</b> Durante disparos no entorno, o professor:</p><ol type=\"a\"><li>Filma para avisar a direção.</li><li>Libera a turma.</li><li>Vai à janela ver o que ocorre.</li><li>Orienta a turma a deitar, longe de janelas e portas.</li></ol></div><div class=\"qz\"><p><b>4.</b> Diante da suspeita de violência contra um aluno, o professor:</p><ol type=\"a\"><li>Espera ter certeza.</li><li>Comenta com outros alunos.</li><li>Investiga com a família.</li><li>Comunica à direção no mesmo dia.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> a) Uma mudança de comportamento que se repete. Importam a mudança e a repetição, não o rótulo.</p><p><b>2.</b> d) \"Se for algo que coloca você em risco, vou precisar pedir ajuda.\" Nunca se promete segredo quando pode haver risco.</p><p><b>3.</b> d) Orienta a turma a deitar, longe de janelas e portas. Deitar e afastar das janelas reduz o risco.</p><p><b>4.</b> d) Comunica à direção no mesmo dia. A escola comunica ao Conselho Tutelar.</p></div>"},{"id":"c31","titulo":"Glossário","html":"<dl><dt>Aliciamento</dt><dd>Aproximação gradual de um adulto ou de um grupo para explorar uma criança ou um adolescente.</dd><dt>Busca ativa</dt><dd>Ação da escola e da rede para localizar e trazer de volta o aluno que deixou de frequentar.</dd><dt>CAPS</dt><dd>Centro de Atenção Psicossocial. Atende sofrimento psíquico intenso e uso de substâncias.</dd><dt>Comportamento mais seguro</dt><dd>Conjunto de condutas que reduzem o risco durante situações de violência armada.</dd><dt>Conselho Tutelar</dt><dd>Órgão que zela pelos direitos de crianças e adolescentes.</dd><dt>CRAS</dt><dd>Centro de Referência de Assistência Social. Atende famílias em vulnerabilidade.</dd><dt>CREAS</dt><dd>Centro de Referência Especializado de Assistência Social. Atende situações de violação de direitos.</dd><dt>Estado de alerta</dt><dd>Condição em que o corpo se mantém preparado para o perigo, o que prejudica a atenção e a memória.</dd><dt>Local mais seguro</dt><dd>Espaço da escola mais protegido de disparos, definido no plano de segurança.</dd><dt>Neutralidade</dt><dd>Princípio pelo qual a escola atende a todos e não toma partido em disputas do território.</dd><dt>Nível de alerta</dt><dd>Grau de risco definido pela direção, com ações combinadas para cada um.</dd><dt>Plano de segurança</dt><dd>Documento que define responsáveis, sinais, locais e procedimentos da escola em situações de risco.</dd><dt>Rede de proteção</dt><dd>Conjunto de serviços que garantem os direitos de crianças e adolescentes.</dd><dt>Território</dt><dd>O bairro e o entorno onde a escola está, com as suas relações e os seus riscos.</dd></dl>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"Um aluno que dorme na aula e se assusta com ruídos pode estar:","alternativas":["Com preguiça.","Desafiando o professor.","Desinteressado.","Em estado de alerta por viver sob tensão."],"correta":3,"explicacao":"A violência afeta sono, atenção e memória."},{"pergunta":"Ao ouvir disparos, o professor orienta a turma a:","alternativas":["Correr para o pátio.","Ficar no chão, longe das janelas.","Olhar pela janela.","Ir para casa."],"correta":1,"explicacao":"Abaixar e afastar-se das áreas expostas."},{"pergunta":"No dia seguinte a um episódio no bairro, o professor:","alternativas":["Passa a aula no assunto.","Finge que nada ocorreu.","Abre um espaço breve para ouvir e retoma a rotina.","Pede detalhes do que viram."],"correta":2,"explicacao":"Ouvir e voltar à rotina."},{"pergunta":"Diante de um aluno cujo pai está preso, o professor:","alternativas":["Trata como qualquer aluno, com discrição.","Pergunta os detalhes.","Evita o aluno.","Comenta com a turma."],"correta":0,"explicacao":"O aluno não é a família."},{"pergunta":"Ao notar sinais de aliciamento, o professor:","alternativas":["Interroga o aluno.","Mantém o vínculo e relata à direção.","Avisa os colegas.","Procura quem alicia."],"correta":1,"explicacao":"A rede de proteção é acionada pela direção."},{"pergunta":"Ao ver um objeto perigoso com um aluno, o professor:","alternativas":["Ignora.","Tenta tomar.","Afasta os demais com discrição e avisa a direção.","Grita."],"correta":2,"explicacao":"Ninguém tenta desarmar."},{"pergunta":"Sobre o território, diante de alunos e responsáveis, o servidor:","alternativas":["Critica grupos.","Elogia operações.","Dá a sua opinião.","Não comenta."],"correta":3,"explicacao":"A escola é neutra para atender a todos."},{"pergunta":"Se for ameaçado, o professor deve:","alternativas":["Resolver sozinho.","Responder à altura.","Afastar-se, avisar a direção e registrar.","Guardar segredo."],"correta":2,"explicacao":"Ninguém enfrenta ameaça sozinho."}];
